query fused_docs($v: Vector(3), $q: String) {
  match {
    let $docs = { match { $d: Doc } return { $d } }
    from rrf(
      nearest($docs, $d.embedding, $v, k: 10),
      bm25($docs, $d.body, $q),
      k: 60
    )
  }
